64:     pub fn check_by_key(&self, key: &str) -> (bool, i64) {
65:         let now = (self.clock)();
66:         let mut buckets = self.buckets.lock().unwrap();
67:         let tier_config = RateLimitTier::Public.config();
68:         let bucket = buckets
69:             .entry(key.to_string())
70:             .or_insert_with(|| RateLimitBucket {
71:                 window_started_at: now,
72:                 attempts: 0,
73:             });
74:         if now - bucket.window_started_at >= self.window_seconds {
75:             bucket.window_started_at = now;
76:             bucket.attempts = 0;
77:         }
78:         if bucket.attempts >= self.max_requests {
79:             let retry_after = tier_config.window_seconds - (now - bucket.window_started_at);
80:             return (false, retry_after);
81:         }
82:         bucket.attempts += 1;
83:         // Evict buckets that have been idle for longer than the window.
84:         buckets.retain(|_, b| now - b.window_started_at < self.window_seconds);
85:         (true, 0)
86:     }
