143: /// Determine the rate-limit tier for a write endpoint based on HTTP method and path.
144: ///
145: /// Path params like `:id`, `:user_id` are treated as wildcards.
146: /// The path is split by `/` and matched segment by segment.
147: pub fn write_endpoint_tier(method: &str, path: &str) -> Option<RateLimitTier> {
148:     let segments: Vec<&str> = path.split('/').collect();
149:     let method = method.to_uppercase();
150: 
151:     // Helper: check if a segment is a path parameter (starts with `:`)
152:     let is_param = |s: &str| s.starts_with(':');
153: 
154:     // Helper: match a segment against a literal or wildcard
155:     let matches = |seg: &str, target: &str| seg == target || is_param(seg);
156: 
157:     // Only allow write methods
158:     let is_write = matches!(method.as_str(), "POST" | "PATCH" | "DELETE" | "PUT");
159:     if !is_write {
160:         return None;
161:     }
162: 
163:     // `*/acl/*/` + (PUT or DELETE) → Critical
164:     for i in 0..segments.len().saturating_sub(1) {
165:         if segments[i] == "acl"
166:             && is_param(segments[i + 1])
167:             && (method == "PUT" || method == "DELETE")
168:         {
169:             return Some(RateLimitTier::Critical);
170:         }
171:     }
172: 
173:     // `*/transfer` + POST → Critical
174:     if segments.len() >= 2 && segments.last() == Some(&"transfer") && method == "POST" {
175:         return Some(RateLimitTier::Critical);
176:     }
177: 
178:     // `*/events` + (POST/PATCH/DELETE) → Standard
179:     // Match both `*/events` and `*/events/*`
180:     for i in 0..segments.len() {
181:         if segments[i] == "events" {
182:             // Match if "events" is the last segment or followed by a parameter
183:             if i + 1 == segments.len() || (i + 1 < segments.len() && is_param(segments[i + 1])) {
184:                 return Some(RateLimitTier::Standard);
185:             }
186:         }
187:     }
188: 
189:     // `*/occurrences/*/` + (PATCH or DELETE) → Standard
190:     for i in 0..segments.len().saturating_sub(1) {
191:         if segments[i] == "occurrences"
192:             && is_param(segments[i + 1])
193:             && (method == "PATCH" || method == "DELETE")
194:         {
195:             return Some(RateLimitTier::Standard);
196:         }
197:     }
198: 
199:     // `*/occurrences/*/following` + PATCH → Standard
200:     for i in 0..segments.len().saturating_sub(2) {
201:         if segments[i] == "occurrences"
202:             && is_param(segments[i + 1])
203:             && matches(segments[i + 2], "following")
204:             && method == "PATCH"
205:         {
206:             return Some(RateLimitTier::Standard);
207:         }
208:     }
209: 
210:     // `*/external-feeds/*/` + (DELETE) → Standard
211:     for i in 0..segments.len().saturating_sub(1) {
212:         if segments[i] == "external-feeds" && is_param(segments[i + 1]) && method == "DELETE" {
213:             return Some(RateLimitTier::Standard);
214:         }
215:     }
216: 
217:     // `*/external-feeds/*/disable` + POST → Standard
218:     for i in 0..segments.len().saturating_sub(2) {
219:         if segments[i] == "external-feeds"
220:             && is_param(segments[i + 1])
221:             && matches(segments[i + 2], "disable")
222:             && method == "POST"
223:         {
224:             return Some(RateLimitTier::Standard);
225:         }
226:     }
227: 
228:     // `*/external-feeds/*/refresh` + POST → Standard
229:     for i in 0..segments.len().saturating_sub(2) {
230:         if segments[i] == "external-feeds"
231:             && is_param(segments[i + 1])
232:             && matches(segments[i + 2], "refresh")
233:             && method == "POST"
234:         {
235:             return Some(RateLimitTier::Standard);
236:         }
237:     }
238: 
239:     // `*/calendars/*/import-ics` + POST → Standard
240:     for i in 0..segments.len().saturating_sub(2) {
241:         if segments[i] == "calendars"
242:             && (is_param(segments[i + 1]) || segments[i + 1].parse::<i64>().is_ok())
243:             && matches(segments[i + 2], "import-ics")
244:             && method == "POST"
245:         {
246:             return Some(RateLimitTier::Standard);
247:         }
248:     }
249: 
250:     // `*/calendars` + (POST/PATCH/DELETE) → Permissive
251:     if segments.len() >= 2 && segments.last() == Some(&"calendars") && method != "GET" {
252:         return Some(RateLimitTier::Permissive);
253:     }
254: 
255:     // `*/calendars/*/archive` + POST → Permissive
256:     for i in 0..segments.len().saturating_sub(2) {
257:         if segments[i] == "calendars"
258:             && is_param(segments[i + 1])
259:             && matches(segments[i + 2], "archive")
260:             && method == "POST"
261:         {
262:             return Some(RateLimitTier::Permissive);
263:         }
264:     }
265: 
266:     // `*/calendars/*/restore` + POST → Permissive
267:     for i in 0..segments.len().saturating_sub(2) {
268:         if segments[i] == "calendars"
269:             && is_param(segments[i + 1])
270:             && matches(segments[i + 2], "restore")
271:             && method == "POST"
272:         {
273:             return Some(RateLimitTier::Permissive);
274:         }
275:     }
276: 
277:     // `*/views/*/` + (POST/PATCH/DELETE) → Permissive
278:     for i in 0..segments.len().saturating_sub(1) {
279:         if segments[i] == "views" && is_param(segments[i + 1]) && method != "GET" {
280:             return Some(RateLimitTier::Permissive);
281:         }
282:     }
283: 
284:     None
285: }
